const textNodes = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
  const node = walker.currentNode;
  if (node.parentElement?.closest('script,style,svg')) continue;
  if (node.textContent.trim()) textNodes.push([node, node.textContent]);
}
const attrs = [];
document.querySelectorAll('[aria-label],[title],[alt]').forEach(el => {
  for (const name of ['aria-label','title','alt']) if (el.hasAttribute(name)) attrs.push([el,name,el.getAttribute(name)]);
});
const metaDescription = document.querySelector('meta[name="description"]');
const englishDescription = metaDescription?.content;
const englishTitle = document.title;
const themeButton = document.querySelector('.theme-toggle');
const languageButton = document.querySelector('.language-toggle');
const translate = text => document.documentElement.lang === 'ar' ? (ar[text] ?? text) : text;
window.siteTranslate = translate;
function applyLanguage(language) {
  const arabic = language === 'ar';
  document.documentElement.lang = arabic ? 'ar' : 'en';
  document.documentElement.dir = arabic ? 'rtl' : 'ltr';
  textNodes.forEach(([node, original]) => {
    const clean = original.trim();
    node.textContent = arabic && ar[clean] ? original.replace(clean, ar[clean]) : original;
  });
  attrs.forEach(([el,name,original]) => el.setAttribute(name, arabic ? (ar[original] ?? original) : original));
  document.title = arabic ? 'ميار | مهندسة كمبيوتر' : 'Mayar | Software Engineer';
  if (metaDescription) metaDescription.content = arabic ? 'ملف أعمال ميار محمد في ضمان جودة البرمجيات، وتجاربها في المنتجات الرقمية والتجارة والرعاية الصحية.' : englishDescription;
  languageButton.textContent = arabic ? 'EN' : 'عربي';
  languageButton.setAttribute('aria-label',arabic ? 'Switch to English' : 'Switch to Arabic');
  languageButton.setAttribute('lang',arabic ? 'en' : 'ar');
  document.querySelector('.nav-preferences')?.setAttribute('aria-label',arabic ? 'تفضيلات العرض' : 'Display preferences');
  document.dispatchEvent(new CustomEvent('site-language-change',{detail:{language}}));
}
function applyTheme(theme) {
  const light = theme === 'light';
  document.documentElement.dataset.theme = light ? 'light' : 'dark';
  themeButton.textContent = light ? '☾' : '☀';
  themeButton.setAttribute('aria-pressed', String(light));
  themeButton.setAttribute('aria-label', document.documentElement.lang === 'ar' ? (light ? 'التبديل إلى الوضع الداكن' : 'التبديل إلى الوضع الفاتح') : (light ? 'Switch to dark mode' : 'Switch to light mode'));
  document.querySelector('meta[name="theme-color"]')?.setAttribute('content', light ? '#f7edf0' : '#151014');
}
const savedLanguage = document.documentElement.lang === 'ar' ? 'ar' : 'en';
const savedTheme = document.documentElement.dataset.theme === 'light' ? 'light' : 'dark';
applyLanguage(savedLanguage);
applyTheme(savedTheme);
languageButton.addEventListener('click', () => {
  const next = document.documentElement.lang === 'ar' ? 'en' : 'ar';
  try { localStorage.setItem('mayar-language', next); } catch (_) {}
  applyLanguage(next);
  applyTheme(document.documentElement.dataset.theme);
  // Live text and carousel state update through site-language-change. No reload is required.
});
themeButton.addEventListener('click', () => {
  const next = document.documentElement.dataset.theme === 'light' ? 'dark' : 'light';
  try { localStorage.setItem('mayar-theme', next); } catch (_) {}
  applyTheme(next);
});
